-- Editor metadata only: compatibility and example assembly do not consume player stock.
create table public.game_component_types(code text primary key check(code ~ '^[a-z][a-z0-9_]{0,59}$'),name_hu text not null check(length(btrim(name_hu)) between 1 and 100),name_en text not null check(length(btrim(name_en)) between 1 and 100));
insert into public.game_component_types values ('barrel','Cső','Barrel'),('receiver','Keret / tok','Receiver / frame'),('handguard','Előágy','Handguard'),('grip','Markolat','Grip'),('stock','Tus','Stock'),('muzzle','Csőszájfék','Muzzle device'),('magazine','Tár','Magazine'),('power_source','Energiaforrás','Power source'),('rail','Szereléksín','Mounting rail'),('optic','Optika','Optic'),('light','Lámpa','Light'),('pointer','Pointer','Pointer'),('shell','Burkolat','Shell'),('lining','Bélés','Lining'),('visor','Rostély','Visor');
create table public.game_equipment_definitions(item_id uuid primary key references public.game_items(id),kind text not null check(kind in ('equipment','component','blueprint')),family text not null check(family in ('weapon','sidearm','armor','helmet')),type_code text references public.game_component_types(code),slots jsonb not null default '[]' check(jsonb_typeof(slots)='array' and jsonb_array_length(slots)<=32),revision integer not null default 1,check((kind='component')=(type_code is not null)),check(kind='blueprint' or slots='[]'));
alter table public.game_component_types enable row level security;alter table public.game_equipment_definitions enable row level security;
revoke all on public.game_component_types,public.game_equipment_definitions from public,anon,authenticated;
create function private.equipment_blueprint_catalog() returns jsonb language plpgsql security definer set search_path='' as $$begin
if auth.uid() is null or not private.can_edit_content() then raise exception 'Editor permission required';end if;
return jsonb_build_object('types',(select coalesce(jsonb_agg(t order by code),'[]') from public.game_component_types t),'definitions',(select coalesce(jsonb_agg(d),'[]') from public.game_equipment_definitions d),'items',(select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'slug',i.slug,'image_path',coalesce(v.image_path,i.image_path),'texts',(select jsonb_agg(t) from public.game_items_i18n t where t.item_id=i.id)) order by i.slug),'[]') from public.game_items i left join public.game_item_combat_visuals v on v.item_id=i.id));end $$;
create function private.save_equipment_blueprint(p_item uuid,p_document jsonb,p_revision integer) returns jsonb language plpgsql security definer set search_path='' as $$declare oldrev integer;s jsonb;n integer;ids text[]:='{}';part uuid;v jsonb;begin
if auth.uid() is null or not private.can_edit_content() then raise exception 'Editor permission required';end if;
perform pg_advisory_xact_lock(708154930);
select revision into oldrev from public.game_equipment_definitions where item_id=p_item for update;
if oldrev is distinct from p_revision then raise exception 'Content changed; reload';end if;
if jsonb_typeof(p_document->'slots') is distinct from 'array' or jsonb_array_length(p_document->'slots')>32 then raise exception 'Invalid blueprint slots';end if;
-- Never silently break another blueprint when reclassifying a referenced component.
if exists(select 1 from public.game_equipment_definitions d cross join lateral jsonb_array_elements(d.slots) slot where d.item_id<>p_item and slot->'compatible_item_ids' ? p_item::text) and exists(select 1 from public.game_equipment_definitions d where d.item_id=p_item and (d.kind is distinct from p_document->>'kind' or d.family is distinct from p_document->>'family' or d.type_code is distinct from p_document->>'type_code')) then raise exception 'Component is used by a blueprint';end if;
for s in select * from jsonb_array_elements(p_document->'slots') loop
if jsonb_typeof(s) is distinct from 'object' or coalesce(length(s->>'id'),0) not between 1 and 80 or (s->>'id')=any(ids) then raise exception 'Invalid or duplicate slot';end if;ids:=array_append(ids,s->>'id');
if not exists(select 1 from public.game_component_types where code=s->>'type_code') or jsonb_typeof(s->'required') is distinct from 'boolean' or jsonb_typeof(s->'compatible_item_ids') is distinct from 'array' or jsonb_array_length(s->'compatible_item_ids')>100 then raise exception 'Invalid slot definition';end if;
if (select count(*)<>count(distinct val) from jsonb_array_elements_text(s->'compatible_item_ids') val) then raise exception 'Duplicate compatible component';end if;
for part in select value::uuid from jsonb_array_elements_text(s->'compatible_item_ids') loop
if part=p_item or not exists(select 1 from public.game_equipment_definitions d where d.item_id=part and d.kind='component' and d.family=p_document->>'family' and d.type_code=s->>'type_code') then raise exception 'Incompatible component';end if;end loop;
if nullif(s->>'selected_item_id','') is not null and not (s->'compatible_item_ids' ? (s->>'selected_item_id')) then raise exception 'Selected component is not compatible';end if;
if coalesce((s->>'x')::numeric between 0 and 100,false)=false or coalesce((s->>'y')::numeric between 0 and 100,false)=false or coalesce((s->>'scale')::numeric between .01 and 4,false)=false or coalesce((s->>'rotation')::numeric between -180 and 180,false)=false then raise exception 'Invalid component placement';end if;
end loop;
insert into public.game_equipment_definitions values(p_item,p_document->>'kind',p_document->>'family',p_document->>'type_code',p_document->'slots',coalesce(oldrev,0)+1) on conflict(item_id) do update set kind=excluded.kind,family=excluded.family,type_code=excluded.type_code,slots=excluded.slots,revision=excluded.revision returning to_jsonb(game_equipment_definitions) into v;return v;
end $$;
create function private.add_component_type(p_code text,p_hu text,p_en text) returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null or not private.can_edit_content() then raise exception 'Editor permission required';end if;insert into public.game_component_types values(p_code,p_hu,p_en);end $$;
create function public.get_equipment_blueprint_catalog() returns jsonb language sql security invoker set search_path='' as $$select private.equipment_blueprint_catalog()$$;
create function public.save_equipment_blueprint(p_item uuid,p_document jsonb,p_revision integer default null) returns jsonb language sql security invoker set search_path='' as $$select private.save_equipment_blueprint(p_item,p_document,p_revision)$$;
create function public.add_component_type(p_code text,p_hu text,p_en text) returns void language sql security invoker set search_path='' as $$select private.add_component_type(p_code,p_hu,p_en)$$;
revoke all on function private.equipment_blueprint_catalog(),private.save_equipment_blueprint(uuid,jsonb,integer),private.add_component_type(text,text,text),public.get_equipment_blueprint_catalog(),public.save_equipment_blueprint(uuid,jsonb,integer),public.add_component_type(text,text,text) from public,anon;
grant execute on function private.equipment_blueprint_catalog(),private.save_equipment_blueprint(uuid,jsonb,integer),private.add_component_type(text,text,text),public.get_equipment_blueprint_catalog(),public.save_equipment_blueprint(uuid,jsonb,integer),public.add_component_type(text,text,text) to authenticated;
